mapper.select:
SELECT , u.real_name as user_name FROM orders o LEFT JOIN sys_user u ON o.user_id = u.id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.user_id = #{userId}
AND o.status = #{status}
AND o.receiver_name LIKE CONCAT('%', #{receiverName}, '%')
ORDER BY o.create_time DESC

mapper.update:
UPDATE orders
pay_amount = #{payAmount}, status = #{status}, receiver_name = #{receiverName}, receiver_phone = #{receiverPhone}, receiver_address = #{receiverAddress},
WHERE id = #{id}
